(function () {
  function initRadarChart() {
    var dom = document.getElementById('radar-chart');
    if (!dom) return;

    // Use CSS variables for theme colors
    var style = getComputedStyle(document.documentElement);
    var accent = style.getPropertyValue('--accent').trim() || '#38bdf8';
    var accent2 = style.getPropertyValue('--accent2').trim() || '#a78bfa';
    var ink = style.getPropertyValue('--ink').trim() || '#e2e8f0';
    var muted = style.getPropertyValue('--muted').trim() || '#94a3b8';
    var bg2 = style.getPropertyValue('--bg2').trim() || '#1e293b';

    var chart = echarts.init(dom);
    var option = {
      backgroundColor: 'transparent',
      tooltip: {
        trigger: 'item',
        backgroundColor: bg2,
        borderColor: accent,
        borderWidth: 1,
        textStyle: { color: ink, fontSize: 13 }
      },
      radar: {
        indicator: [
          { name: '目标设定\nGoal Setting', max: 100 },
          { name: '任务分解策略\nTask Decomposition', max: 100 },
          { name: '上下文与状态管理\nContext & State', max: 100 },
          { name: '自主决策与异常处理\nAgent Decision & Exception', max: 100 },
          { name: '进度检查点与自我评估\nCheckpoints & Assessment', max: 100 },
          { name: '输出规范\nOutput Specifications', max: 100 },
          { name: '资源与边界约束\nResources & Boundaries', max: 100 }
        ],
        center: ['50%', '50%'],
        radius: '65%',
        splitNumber: 4,
        shape: 'polygon',
        axisName: {
          color: ink,
          fontSize: 12,
          fontFamily: 'system-ui, sans-serif',
          lineHeight: 18
        },
        splitLine: {
          lineStyle: { color: 'rgba(148, 163, 184, 0.15)' }
        },
        splitArea: {
          areaStyle: {
            color: ['rgba(30, 41, 59, 0.4)', 'rgba(30, 41, 59, 0.2)']
          }
        },
        axisLine: {
          lineStyle: { color: 'rgba(148, 163, 184, 0.2)' }
        }
      },
      series: [
        {
          type: 'radar',
          data: [
            {
              value: [95, 90, 85, 80, 75, 85, 70],
              name: '重要性评分',
              areaStyle: {
                color: {
                  type: 'radial',
                  x: 0.5,
                  y: 0.5,
                  r: 0.5,
                  colorStops: [
                    { offset: 0, color: accent2 + '60' },
                    { offset: 1, color: accent + '20' }
                  ]
                }
              },
              lineStyle: {
                color: accent,
                width: 2
              },
              itemStyle: {
                color: accent2
              }
            }
          ]
        }
      ]
    };

    chart.setOption(option);

    // Resize handler
    window.addEventListener('resize', function () {
      chart.resize();
    });
  }

  // Wait for DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initRadarChart);
  } else {
    initRadarChart();
  }
})();